mapper.select:
SELECT id,
       platform,
       bot_id        AS botId,
       group_id      AS groupId,
       user_id_a     AS userIdA,
       user_id_b     AS userIdB,
       relation_kind AS relationKind,
       strength,
       updated_at    AS updatedAt
FROM member_relation
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}
  AND user_id_a = #{userIdA}
  AND user_id_b = #{userIdB}
